scwin.fn_SetPar;
scwin.fn_GetPar;
// scwin.vScrenID = 'ULDFIS00500.gfm';
// 전역 변수 선언
scwin.search_ACCNT_PTTN = ""; // 검색시 수정된 유형
scwin.search_IND_PTTN = "";
// scwin.vSecugrpID = SECUGRP_ID_ST;
scwin.queryId;

// scwin.onpageload, scwin.onpageunload 함수
scwin.onpageload = function() {
    // const codeOptions = [ 
    //     { code : "sndloc_tp_cd", compID : "cmb_sndloc_tp_cd" },  //송신처구분코드
    //     { code : "discls_kind_cd", compID : "cmb_discls_kind_cd" }, //공시종류코드
    //     { code : "discls_procs_stat_cd", compID : "grd_Grid:disclsProcsStatCd" },    //공시처리상태코드
    // ];
    // await $c.data.setCommonCode(codeOptions);
    grd_comList.setColumnWidth("nm", 230); //첫번째 컬럼의 width가 0이 되는 현상이 있어서 임의로 지정해줌 (코드에 안 보이는것 같은데 원인을 모르겠음)
    scwin.gform_onload();
};

scwin.onpageunload = function() {
};

// WebSquare 컴포넌트 이벤트 함수
scwin.btn_excel_onclick = function(e) {
    if (grd_comList.getRowCount() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }

    // grd_comList.GridToExcel("요약재무정보", "", "2"); //엑셀 다운로드
    $c.data.downloadGridViewExcel(grd_comList, {fileName: "", sheetName: "요약재무정보"});
};

scwin.btn_search_onclick = function(e) {
    scwin.initialize();
    scwin.inspecOp();
};

scwin.btn_coSearch_onclick = function(e) {
    scwin.comSrchOpen();
};

scwin.ibx_coSnm_onchange = function() {
    // 조회조건이 변경된 경우 초기화.
    ibx_kisCd.setValue("");
    ibx_indPttn.setValue("");
};

scwin.ibx_coSnm_onkeydown = function(e) {
    // 기업명 키다운.
    if (e.keyCode === 13) {

        //----W-Craft WebSquare 변환 확인: focus----//
        frame.focus();
        if (ibx_coSnm.getValue() === "") {
            // 기업검색팝업 오픈
            scwin.comSrchOpen();
        } else {
            // 기업정보 조회
            scwin.comInfoSrch();
        }
    }
};

scwin.grd_comList_OnDblClick = function(row, colid) {
    scwin.openDetail(row);
};

scwin.dts_ComList_OnLoadCompleted = function(rowcount) {
    if (dts_ComList.errorMsg) {
        alert(dts_ComList.errorMsg);
    }
};

scwin.panel_page_onclick = function(e) {
    scwin.accntCdOpen();
};

// 일반 함수
 // 검색시 수정된 업종유형

/**
 *  재무 환경데이터를 조회한다
 */
scwin.inspecOp = function() {
    if (ibx_coSnm.getValue() === "") {
        alert("조회 기업을 검색해 주세요");

        //----W-Craft WebSquare 변환 확인: focus----//
        ibx_coSnm.focus();
        return false;
    }

    let reqMap = {
        shType: sbx_shType.getValue(), //조회형식 //값은 왜 2?
        kisCd: ibx_kisCd.getValue(), //기업코드
        accStand: sbx_accStand.getValue(), //회계기준코드
        setTime: sbx_setTime.getValue(), //결산시점코드
        eachConn: sbx_eachConn.getValue(), //개별/연결구분코드
        closing: sbx_closing.getValue(), //결산년도
    };
    $c.sbm.execute(sbm_inspecOp, reqMap);
};

/**
 *  재무 데이터를 조회한다
 */
scwin.search3 = function() {

    // 자본변동표인경우 계정코드가 요약이 없어 재무전체로 변경한다
    if (sbx_type.getValue() === "6") {
        rdo_type.getValue().setValue(2);
    }

    // 제조업일경우 유형을 4(현금흐름표)일경우 6으로 바꿔준다 6(자본변동표)인경우 -> 업종유형을 2로 바꿔준다
    scwin.search_ACCNT_PTTN = sbx_type.getValue();
    scwin.search_IND_PTTN = ibx_indPttn.getValue();
    if (ibx_indPttn.getValue() === "1") {
        if (sbx_type.getValue() === "4") {
            scwin.search_ACCNT_PTTN = "6";
        } else if (sbx_type.getValue() === "6") {
            scwin.search_IND_PTTN = "2";
        }
    }
    if (sbx_shType.getValue() === "1") {
        scwin.queryId = "krx.lds.stf.fis.select.sameTime";
    } else {
        scwin.queryId = "krx.lds.stf.fis.select.finQuarter";
    }

    let reqMap = {
        kisCd: ibx_kisCd.getValue(), //기업코드
        closing: sbx_closing.getValue(), //결산년도
        accntPttn: scwin.search_ACCNT_PTTN, //유형
        searchType: sbx_searchType.getValue(), //검색유형
        unit: sbx_unit.getValue(), //단위
        accStand: sbx_accStand.getValue(), //회계기준코드
        eachConn: sbx_eachConn.getValue(), //개별/연결구분코드
        setTime: sbx_setTime.getValue(), //결산시점코드
        type: rdo_type.getValue(), //요약/표준
        // indPttn: scwin.search_IND_PTTN, //업종유형
        indPttn: "1", //업종유형 TEST 어디서 가져오는 값이지? 기업조회인가?
    };
    $c.sbm.execute(sbm_comFindata, reqMap);
};

/**
 * 팝업으로 값을 넘김.
 */
scwin.getParKisCd = function() {
    let arrPar = new Array();
    arrPar[0] = ibx_coSnm.getValue(); // 기업명
    return arrPar;
};

/**
 * 팝업에서 넘어온 값 세팅.
 */
// scwin.fn_SetParKisCd = function(arrPar) {
//     ibx_coSnm.setValue(arrPar[0].CO_SNM); //기업명
//     ibx_kisCd.setValue(arrPar[0].KIS_CD); //기업코드
//     ibx_indPttn.setValue(arrPar[0].IND_PTTN);

//     if (ibx_kisCd.getValue() != "") {
//         scwin.fn_InspecOp();
//     }
// };


/**
 * 기업검색 팝업
 */
scwin.comSrchOpen = async function() {

    //----W-Craft WebSquare 변환 확인: CreateDialogFrame----//
    // frame.CreateDialogFrame("KIS_CD", "./ULDFIS00100_P1.gfm", "기업 검색", 100, 100, 640 + 20, 445 + 45, "window");

    const url = "/ui/lst/fis/ULDFIS00101.xml";
    const popTitle = "기업 검색";

    const opts = {
        id: "ULDFIS00101",
        popupName: popTitle,
        width: 900,
        height: 679,
        frameModal: "top",
    };

    const res = await $c.win.openPopup(url, opts);

    ibx_coSnm.setValue(res.coSnm); //기업명
    ibx_kisCd.setValue(res.kisCd); //기업코드
    ibx_indPttn.setValue(res.indPttn); //업종유형

    if (ibx_kisCd.getValue() !== "") {
        scwin.inspecOp();
    }
};

/**
 *  조회조건 유효성 체크
 */
scwin.chkValid = function() {
    //필수항목 체크.
    if (ibx_coSnm.getValue() === "") {
        alert("기업명을 입력하세요.");

        //----W-Craft WebSquare 변환 확인: focus----//
        ibx_coSnm.focus();
        return false;
    }

    // 기업명은 있는데 기업코드가 없는 경우
    if (ibx_coSnm.getValue() !== "" && ibx_kisCd.getValue() === "") {
        scwin.comInfoSrch();
        return false;
    }
    return true;
};

/**
 * 선택된 값을 오프너에 전달한다.
 */
scwin.openDetail = function(v_Currow) {
    if (v_Currow === undefined) {
        v_Currow = dts_ComList.getRowPosition(); // TODO Stage2: 0-based 검토
    }
    let arrPar = new Array();
    if (scwin.fn_SetPar !== undefined) {
        arrPar[0] = {

            //----W-Craft WebSquare 변환 확인: NameString----//
            nm: dts_ComList.getCellData(v_Currow, "nm"), //기업명	

            //----W-Craft WebSquare 변환 확인: NameString----//
            data_op1_1: dts_ComList.getCellData(v_Currow, "data_op1_1"), //금액1	

            //----W-Craft WebSquare 변환 확인: NameString----//
            data_op1_2: dts_ComList.getCellData(v_Currow, "data_op1_2"), //구성비1	

            //----W-Craft WebSquare 변환 확인: NameString----//
            data_op2_1: dts_ComList.getCellData(v_Currow, "data_op2_1"), //금액2	

            //----W-Craft WebSquare 변환 확인: NameString----//
            data_op2_2: dts_ComList.getCellData(v_Currow, "data_op2_2"), //구성비2	

            //----W-Craft WebSquare 변환 확인: NameString----//
            data_op3_1: dts_ComList.getCellData(v_Currow, "data_op3_1"), //금액3	

            //----W-Craft WebSquare 변환 확인: NameString----//
            data_op3_2: dts_ComList.getCellData(v_Currow, "data_op3_2"), //구성비3	

            //----W-Craft WebSquare 변환 확인: NameString----//
            data_op4_1: dts_ComList.getCellData(v_Currow, "data_op4_1"), //금액4	

            //----W-Craft WebSquare 변환 확인: NameString----//
            data_op4_2: dts_ComList.getCellData(v_Currow, "data_op4_2") //구성비4
        };
        //fn_SetPar(arrPar);

    }
    // frame.CloseFrame();

};

/**
 * 기업정보 조회(명으로 조회)
 */
scwin.comInfoSrch = function() {
    //데이터셋 초기화
    dts_ComList.setJSON([]);
    const sbmOptions = {
        id : "sbm_dts_ComInfo",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_ComInfo=body.content",
        // TODO Stage2: submitdone 핸들러 미정의 (scwin.sbm_dts_ComInfo_submitdone 정의 없음, 정적 submission 노드도 없음)
        submitDoneHandler : scwin.sbm_dts_ComInfo_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);



    // 조회결과가 1개이면 기업개황 조회 아니면 기업팝업 오픈.
    if (dts_ComInfo.getRowCount() === 1) {
        // 조회조건에 값을 세팅하고..

        //----W-Craft WebSquare 변환 확인: NameString----//
        ibx_kisCd.setValue(dts_ComInfo.getCellData(0, "KIS_CD"));

        //----W-Craft WebSquare 변환 확인: NameString----//
        ibx_indPttn.setValue(dts_ComInfo.getCellData(0, "IND_PTTN"));
        scwin.inspecOp(); // 기업개황 조회

    } else {
        scwin.comSrchOpen(); //기업검색 팝업 오픈

    }
};

/**
 * 결산연도를 가져온다
 */
scwin.firstSet = function() {
    scwin.firstSetSearch();
};

scwin.firstSetSearch = async function() {
    const sbmOptions = {
        id : "sbm_fiscal_yyyy",
        action : "/api/listing/nice/financial/fiscal-yyyy",
        method : "get",
        target : "dlt_closingRes",
        isProcessMsg : false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    dlt_closingRes.setJSON(res.responseJSON.body);
}

/**
 * 상단 HEADER 부분 초기화
 */
scwin.initialize = function() {
    grd_comList.setHeaderValue("column3", "");
    grd_comList.setHeaderValue("column4", "");
    grd_comList.setHeaderValue("column5", "");
    grd_comList.setHeaderValue("column6", "");
    grd_comList.setHeaderValue("h_inspection1", "");
    grd_comList.setHeaderValue("h_inspection2", "");
    grd_comList.setHeaderValue("h_inspection3", "");
    grd_comList.setHeaderValue("h_inspection4", "");
    grd_comList.setHeaderValue("h_data_op1_1", "");
    grd_comList.setHeaderValue("h_data_op2_1", "");
    grd_comList.setHeaderValue("h_data_op3_1", "");
    grd_comList.setHeaderValue("h_data_op4_1", "");
    grd_comList.setHeaderValue("h_data_op1_2", "");
    grd_comList.setHeaderValue("h_data_op2_2", "");
    grd_comList.setHeaderValue("h_data_op3_2", "");
    grd_comList.setHeaderValue("h_data_op4_2", "");
};

/**
 * 감사의견 세팅
 */
scwin.getOpiText = function(opiCode) {
    let opiText = "";
    if (opiCode === "10") opiText = "적정";
    if (opiCode === "20") opiText = "한정";
    if (opiCode === "21") opiText = "한정-감사범위제한";
    if (opiCode === "22") opiText = "한정-기업회계기준위배";
    if (opiCode === "30") opiText = "부적정";
    if (opiCode === "31") opiText = "부적정 -계속기업존속의문시";
    if (opiCode === "40") opiText = "의견거절";
    if (opiCode === "41") opiText = "의견거절-독립성결";
    if (opiCode === "42") opiText = "의견거절-감사범위제한";
    if (opiCode === "43") opiText = "의견거절-계속기업존속의문시";
    if (opiCode === "50") opiText = "감사미필";
    if (opiCode === "70") opiText = "검토(표준)";
    if (opiCode === "71") opiText = "검토(한정)";
    if (opiCode === "72") opiText = "검토(부적정)";
    if (opiCode === "73") opiText = "검토(의견거절)";
    if (opiCode === "80") opiText = "미검토";
    return opiText;
};

/**
 * 계정코드 변경
 */
scwin.accntCdOpen = function() {

    //----W-Craft WebSquare 변환 확인: CreateDialogFrame----//
    const options = {
        id: "ULDFIS00600_P10",
        title: "재무계정검색",
        type: "browserPopup",
        width: 683 + 20,
        height: 485 + 40
    };

    const data = {
        // TO-DO : 팝업으로 전달할 파라미터 설정,
        callbackFn: "scwin.popupCallback"
    };

    const result = await $c.win.openPopup("./ULDFIS00600_P10.gfm", options, data);
    scwin.popupCallback(result);
};

scwin.gform_onload = function() {
    // $c.libRoundPanel.PanelToGroupBox(panel_1);
    scwin.firstSet();
};

scwin.sbm_inspecOp_submitdone = function (e) {
    let res = e.responseJSON.body
    dlt_inspecOpRes.setJSON(res);

    if (sbx_searchType.getValue() === '1') {
        searchTypeNM = '구성비';
    } else {
        searchTypeNM = '증감률';
    }
    for (let i = 0; i < dlt_inspecOpRes.getRowCount(); i++) {

        //----W-Craft WebSquare 변환 확인: NameString----//
        const fiscal_typ = dlt_inspecOpRes.getCellData(i, "fiscalTyp");
        let fiscal_mm_text = "";
        if (fiscal_typ === 'K') fiscal_mm_text = '온기';

        else if (fiscal_typ === 'T') fiscal_mm_text = '3분기(누적)';

        else if (fiscal_typ === 'B') fiscal_mm_text = '반기';

        else if (fiscal_typ === 'F') fiscal_mm_text = '1분기';

        else if (fiscal_typ === 'X') fiscal_mm_text = '2분기';

        else if (fiscal_typ === 'Y') fiscal_mm_text = '3분기';


        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        //----W-Craft WebSquare 변환 확인: NameString----//
        else if (fiscal_typ === 'Z') fiscal_mm_text = '4분기'; 
        /*ORG SRC: grd_comList.ColumnProp(i + "date", "Name") = dlt_inspecOpRes.getCellData(i, "FISCAL_YYYY") + "년 " + dlt_inspecOpRes.getCellData(i, "FISCAL_MM") + "월 (" + fiscal_mm_text + ")";*/ 
        grd_comList.setHeaderValue("column" + (i+3), dlt_inspecOpRes.getCellData(i, "fiscalYyyy") + "년 " + dlt_inspecOpRes.getCellData(i, "fiscalMm") + "월 (" + fiscal_mm_text + ")");

        //----W-Craft WebSquare 변환 확인: NameString----//
        const ISU_ADMIN_YN = (dlt_inspecOpRes.getCellData(i, "isuAdminYn") === "Y") ? "관리종목" : "관련없음";

        //----W-Craft WebSquare 변환 확인: NameString----//
        const AUDT_OPIN_LDIV = dlt_inspecOpRes.getCellData(i, "audtOpinLdiv");

        //----W-Craft WebSquare 변환 확인: NameString----//
        const AUDT_OPIN_MDIV = dlt_inspecOpRes.getCellData(i, "audtOpinMdiv"); 
        /*ORG SRC: grd_comList.ColumnProp("inspection" + String(i), "Name") = getOpiText(AUDT_OPIN_LDIV + AUDT_OPIN_MDIV) + " / " + ISU_ADMIN_YN;*/ 
        grd_comList.setHeaderValue("h_inspection" + String(i+1), scwin.getOpiText(AUDT_OPIN_LDIV + AUDT_OPIN_MDIV) + " / " + ISU_ADMIN_YN);
        grd_comList.setHeaderValue("h_data_op" + (i+1) + "_1", "금액");
        grd_comList.setHeaderValue("h_data_op" + (i+1) + "_2", searchTypeNM);
        /*ORG SRC: grd_comList.ColumnProp("data_op" + i + "_1", "Name") = "금액";*/;
        /*ORG SRC: grd_comList.ColumnProp("data_op" + i + "_2", "Name") = searchTypeNM;*/;
    }
    scwin.search3();
};

scwin.sbm_comFindata_submitdone = function (e) {
    dlt_comFindataRes.setJSON(e.responseJSON.body);
    tbx_totCnt.setValue(dlt_comFindataRes.getRowCount());
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {String | Number} arg 팝업에서 전달받은 값
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};
